serviceSyncExecute.source:
function (service, args) {
            if (!args?.api) {
                console.error('wrong parameter, should set api')
                return false
            }

            if (this.httpRequest == null) {
                this.httpRequest = new XMLHttpRequest()
            }

            if (!this.portValidated) {
                const options = [
                    'https://localhost:9888/service/',
                    'http://localhost:9009/service/'
                ]

                for (const option of options) {
                    const url = option + service
                    const result = this.executeHttpRequest(url, args)

                    if (result.success) {
                        this.httpOption = option
                        this.portValidated = true
                        console.log(`request ok: ${option}`)
                        return result.data
                    }
                }

                this.portValidated = true
                console.warn('all attempt are invalid, use default https.')
                return false
            }

            const finalUrl = this.httpOption + service
            const finalResult = this.executeHttpRequest(finalUrl, args)

            return finalResult.success ? finalResult.data : false
        }

